import math
    import random
    import time

    LANGUAGE_WRAPPER = 'Fix integers {base} >= 3 and {modulus} >= 3. Let R be the contiguous block of residues {start_residue}, {start_residue}+1, ..., {start_residue}+{subset_size}-1 taken modulo {modulus}. Let the rational shift be tau = {tau_num}/{tau_den} with 0 < tau < 1. For each real x in [0,1), define\nf(x) = sum over all positive integers n such that floor(n*x + tau) modulo {modulus} lies in R, of 1/{base}^n.\nLet L_max be the largest real number such that f(x) >= L_max for all x in [0,1). Determine the largest integer strictly less than {scale} * L_max.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We choose parameters to ensure the verifier can stably compute the exact floor
# and to make the instance non-trivial.
# Base is at least 5 so tail is tiny; modulus >= 3; subset_size in [1, modulus-1].
base = rng.randint(5, 8)  # q <= 0.2
modulus = rng.randint(3, 7)
subset_size = rng.randint(1, modulus - 1)
start_residue = rng.randint(0, modulus - 1)
# Choose a small denominator for tau to keep boundary structure rich but manageable.
tau_den = rng.choice([2, 3, 4, 5, 6, 7, 8])
tau_num = rng.randint(1, tau_den - 1)
# Scale choices; 1000 common but we vary.
scale = rng.choice([500, 1000, 2000, 2500])
return {
    'base': base,
    'modulus': modulus,
    'subset_size': subset_size,
    'start_residue': start_residue,
    'tau_num': tau_num,
    'tau_den': tau_den,
    'scale': scale
}

