# Recompute, validate domain constraints, and return (True, answer)
# The answer is floor(scale * L_max), where L_max = inf_{x in [0,1)} f(x).
import math

# Extract and validate parameters
try:
    base = int(assign['base'])
    modulus = int(assign['modulus'])
    subset_size = int(assign['subset_size'])
    start_residue = int(assign['start_residue'])
    tau_num = int(assign['tau_num'])
    tau_den = int(assign['tau_den'])
    scale = int(assign['scale'])
except Exception:
    # Missing or invalid types
    return (False, None)  # invalid assignment

# Basic domain checks
if base < 3 or modulus < 3:
    return (False, None)  # invalid assignment
if subset_size <= 0 or subset_size >= modulus:
    return (False, None)  # trivial or invalid residue block
if not (0 <= start_residue < modulus):
    return (False, None)
if tau_den <= 0 or tau_num <= 0 or tau_num >= tau_den:
    return (False, None)
if scale <= 0:
    return (False, None)

# Define parameters for computation
tau = tau_num / tau_den
q = 1.0 / float(base)

# Indicator for membership in the contiguous residue block modulo 'modulus'
def in_block(res):
    # res in Z; check if res mod modulus lies in {start_residue, ..., start_residue+subset_size-1} mod modulus
    return ((res - start_residue) % modulus) < subset_size

# Compute f_N(x) piecewise constant on intervals with breakpoints at (k - tau)/n for n <= N
def compute_min_partial(N):
    # Build breakpoints in [0,1], including 0 and 1
    points = [0.0, 1.0]
    for n in range(1, N + 1):
        # k runs from 0..n; x = (k - tau)/n
        for k in range(0, n + 1):
            x = (k - tau) / n
            if 0.0 <= x <= 1.0:
                points.append(x)
    # Sort and deduplicate with tolerance
    points.sort()
    dedup = []
    eps = 1e-12
    for x in points:
        if not dedup or abs(x - dedup[-1]) > eps:
            dedup.append(x)
    points = dedup
    # Precompute powers q^n
    pows = [q ** n for n in range(1, N + 1)]

    def f_partial(x):
        s = 0.0
        # Evaluate f_N(x) = sum_{n=1..N} q^n * I( floor(n x + tau) mod modulus in block )
        for n in range(1, N + 1):
            val = math.floor(n * x + tau)
            if in_block(int(val)):
                s += pows[n - 1]
        return s

    # Evaluate midpoints between consecutive breakpoints; also include endpoint x=0 exactly
    min_val = float('inf')
    # include exact endpoint 0
    v0 = f_partial(0.0)
    if v0 < min_val:
        min_val = v0
    for i in range(len(points) - 1):
        a = points[i]
        b = points[i + 1]
        if b <= a:
            continue
        x = (a + b) / 2.0
        val = f_partial(x)
        if val < min_val:
            min_val = val
    return min_val

# Iteratively refine N until floor(scale * LB) == floor(scale * UB)
# LB = min f_N; UB = LB + tail_max where tail_max = sum_{n>N} q^n.
# This guarantees exact floor once the interval lies within a single integer bin.
N = 40  # start moderate
maxN = 140
last_floor_pair = None
while True:
    LB = compute_min_partial(N)
    tail_max = (q ** (N + 1)) / (1.0 - q)
    UB = LB + tail_max
    floLB = int(math.floor(scale * LB + 1e-12))
    floUB = int(math.floor(scale * UB + 1e-12))
    if floLB == floUB:
        answer = floLB
        return (True, answer)
    # If not stable, increase N
    N += 20
    if N > maxN:
        # As a safety fallback, try a stricter check: if the interval [LB, UB] lies entirely within one open unit bin.
        # Compute the next integer thresholds around scale*LB
        sLB = scale * LB
        sUB = scale * UB
        fLB = math.floor(sLB)
        fUB = math.floor(sUB)
        if fLB == fUB and int(fLB) == floLB:
            return (True, floLB)
        # Otherwise, give up: the assignment is too close to a boundary for our capped N.
        return (False, None)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

